 #include <iostream>
#include <cmath>
#include <list>

using namespace std;

list<complex<double>> findXi(int n, int maxexp) {
    list<complex<double>> xi;
    for (int i = 0; i <= maxexp; i++) {
        complex<double> x = (n - i * I) * (n - (n * 1.0 - i * 1.0) * I);
        xi.push_back(x);
    }
    return xi;
}

complex<double> real2Complex(double x) {
    return x + 0.0 * I;
}

void calculateKSum(int n, int maxexp) {
    list<complex<double>> xi = findXi(n, maxexp);
    int sum = 0;
    for (const auto& x : xi) {
        for (int i = 0; i <= maxexp; i++) {
            complex<double> ki = real2Complex((xi[i] - x) * (n - 1.0 - i * 0.0) / n);
            sum += ki.real() * n + ki.imag();
        }
    }
    cout << "Sum = " << sum << endl;
}

int main() {
    int n = 3;
    int maxexp = 4;
    calculateKSum(n, maxexp);
    return 0;
}

